def eval_rpn(tokens):
    st = []
    for t in tokens:
        if t in '+-*/':
            b = st.pop(); a = st.pop()
            if t == '+': st.append(a + b)
            elif t == '-': st.append(a - b)
            elif t == '*': st.append(a * b)
            else: st.append(int(a / b))
        else:
            st.append(int(t))
    return st[-1]

print(eval_rpn(['4', '13', '5', '/', '+']))
```

This min-stack stores pairs `(value, min_so_far)`. What does `ms.get_min()` return at the end?

```python
class MinStack:
    def __init__(self):
        self.st = []
    def push(self, x):
        m = x if not self.st else min(x, self.st[-1][1])
        self.st.append((x, m))
    def pop(self):
        self.st.pop()
    def get_min(self):
        return self.st[-1][1]

ms = MinStack()
ms.push(5); ms.push(3); ms.push(7); ms.pop(); ms.push(2); ms.pop()
print(ms.get_min())
```

